	c.SessionID = avp.CloneString(c.SessionID)
	c.VendorSpecificApplicationID = *base.CloneVSAI(&c.VendorSpecificApplicationID)
	c.OriginHost = avp.CloneString(c.OriginHost)
	c.OriginRealm = avp.CloneString(c.OriginRealm)
	if c.DestinationHost.Present {
		c.DestinationHost.Value = avp.CloneString(c.DestinationHost.Value)
	} else {
		c.DestinationHost = avp.Optional[string]{}
	}
	c.DestinationRealm = avp.CloneString(c.DestinationRealm)
