func envelopePUA(b pdu.Body) (pdu.Envelope, error) {
	m, ok := b.(*PUA)
	if !ok || m == nil {
		return pdu.Envelope{}, validation.ErrType
	}
	var out pdu.Envelope
	out.SessionID = avp.Some(m.SessionID)
	out.AuthSessionState = avp.Some(m.AuthSessionState)
	out.Origin.Host = m.OriginHost
	out.Origin.Realm = m.OriginRealm
	out.ProxyInfo = m.ProxyInfo
	return out, nil
}
func answerPUA(b pdu.Body, env pdu.AnswerEnvelope) (pdu.Body, error) {
	m, ok := b.(*PUA)
	if !ok || m == nil {
		return nil, validation.ErrType
	}
	out := clonePUA(m)
	var session avp.Optional[string]
	var host, realm string
	var proxy []pdu.ProxyInfo
	if out.SessionID != "" {
		session = avp.Some(out.SessionID)
	}
	host = out.OriginHost
	realm = out.OriginRealm
	proxy = out.ProxyInfo
	_ = session
	_ = proxy
	if err := base.CompleteEnvelopeValues(&session, &host, &realm, &proxy, env); err != nil {
		return nil, err
	}
	out.SessionID = session.Value
	out.OriginHost = host
	out.OriginRealm = realm
	out.ProxyInfo = proxy
	return out, nil
}
